local CopperSheetMaker = {}
local PRODUCTS = {
    simple_copper_sheet = { name = "Preprost bakerjev pločevina", copperCost = 3, time = 3, cost = 70, science = 15, happiness = 1, description = "Preprost bakerjev pločevina za obloge." }
    , bronze_alloy_sheet = { name = "Bronastazlitna pločevina", copperCost = 2, bronzeCost = 2, time = 5, cost = 180, science = 28, happiness = 1, prestige = 2, description = "Bronastazlitna pločevina za trgovce." },
    silver_plated_sheet = { name = "Srebrnopolirana pločevina", copperCost = 2, bronzeCost = 1, silverCost = 1, time = 8, cost = 440, science = 42, happiness = 2, prestige = 6, description = "Srebrnopolirana pločevina za plemiče." },
    gold_trimmed_sheet = { name = "Zlatookrasna pločevina", copperCost = 2, bronzeCost = 1, goldCost = 1, silverCost = 1, time = 12, cost = 1000, science = 56, happiness = 3, prestige = 14, description = "Zlatookrasna pločevina za visoke plemiče." },
    jewel_set_sheet = { name = "Draguljasta pločevina", copperCost = 2, bronzeCost = 1, goldCost = 1, silverCost = 1, jewelCost = 1, time = 16, cost = 2200, science = 72, happiness = 5, prestige = 27, description = "Pločevina z draguljem za visoko plemstvo." },
    royal_grand_copper_sheet = { name = "Kraljevski veliki bakerjev pločevina", copperCost = 3, bronzeCost = 2, goldCost = 2, silverCost = 2, jewelCost = 2, pearlCost = 2, time = 23, cost = 4800, science = 90, happiness = 12, prestige = 58, description = "Veliki kraljevski bakerjev pločevina z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    sheet_workshop = { name = "Pločevinska delavnica", cost = { gold = 260, wood = 120, stone = 120, copper = 6 }, upkeep = 6, qualityBonus = 5 },
    rolling_loft = { name = "Valjna podstrešje", cost = { gold = 950, wood = 280, stone = 280, silver = 6, bronze = 6 }, upkeep = 22, qualityBonus = 18 },
    master_sheet_atelier = { name = "Mojstrski pločevinski atelje", cost = { gold = 2700, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_sheet_palace = { name = "Kraljevska pločevinska palača", cost = { gold = 11500, wood = 580, stone = 760, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
CopperSheetMaker.copperStock = 16; CopperSheetMaker.bronzeStock = 12; CopperSheetMaker.silverStock = 6; CopperSheetMaker.goldStock = 6; CopperSheetMaker.jewelStock = 4; CopperSheetMaker.pearlStock = 4
CopperSheetMaker.productStock = {}; CopperSheetMaker.buildings = {}; CopperSheetMaker.maker = nil; CopperSheetMaker.activeMaking = {}; CopperSheetMaker.totalProducts = 0; CopperSheetMaker.dayTimer = 0
function CopperSheetMaker.init() CopperSheetMaker.copperStock=16; CopperSheetMaker.bronzeStock=12; CopperSheetMaker.silverStock=6; CopperSheetMaker.goldStock=6; CopperSheetMaker.jewelStock=4; CopperSheetMaker.pearlStock=4; CopperSheetMaker.productStock={}; CopperSheetMaker.buildings={}; CopperSheetMaker.maker=nil; CopperSheetMaker.activeMaking={}; CopperSheetMaker.totalProducts=0; CopperSheetMaker.dayTimer=0; print("[CopperSheetMaker] Royal Copper Sheet Maker System initialized (6 products, 4 buildings)") end
function CopperSheetMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CopperSheetMaker.maker={name=n or ("Pločevinar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pločevinar najet: %s (spretnost: %d)",CopperSheetMaker.maker.name,s),"success") end; return true end
function CopperSheetMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CopperSheetMaker.build(id) local ok,e=CopperSheetMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CopperSheetMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CopperSheetMaker.getQualityBonus() local b=0; for _,bd in ipairs(CopperSheetMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CopperSheetMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.copperCost and CopperSheetMaker.copperStock<(d.copperCost or 0) then return false,"Premalo bakra" end; if d.bronzeCost and CopperSheetMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.silverCost and CopperSheetMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CopperSheetMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CopperSheetMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CopperSheetMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CopperSheetMaker.buildings==0 then return false,"Potrebna pločevinska delavnica" end; if not CopperSheetMaker.maker then return false,"Potreben pločevinar" end; return true end
function CopperSheetMaker.make(pt,qty) qty=qty or 1; local ok,e=CopperSheetMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.copperCost then CopperSheetMaker.copperStock=CopperSheetMaker.copperStock-d.copperCost*qty end; if d.bronzeCost then CopperSheetMaker.bronzeStock=CopperSheetMaker.bronzeStock-d.bronzeCost*qty end; if d.silverCost then CopperSheetMaker.silverStock=CopperSheetMaker.silverStock-d.silverCost*qty end; if d.goldCost then CopperSheetMaker.goldStock=CopperSheetMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CopperSheetMaker.jewelStock=CopperSheetMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CopperSheetMaker.pearlStock=CopperSheetMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CopperSheetMaker.maker then t=math.max(1,t-math.floor(CopperSheetMaker.maker.skill/13)) end; table.insert(CopperSheetMaker.activeMaking,{id="coppersheet_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Valjanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CopperSheetMaker.completeMaking(m) local q=1.0+(CopperSheetMaker.getQualityBonus()/100); if CopperSheetMaker.maker then q=q+(CopperSheetMaker.maker.skill/140) end; q=math.min(2.5,q); CopperSheetMaker.productStock[m.productType]=(CopperSheetMaker.productStock[m.productType] or 0)+m.quantity; CopperSheetMaker.totalProducts=CopperSheetMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CopperSheetMaker.maker then CopperSheetMaker.maker.itemsMade=CopperSheetMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CopperSheetMaker.maker.skill=math.min(100,CopperSheetMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pločevina izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"coppersheet.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function CopperSheetMaker.update(dt) if not _G.state then return end; CopperSheetMaker.dayTimer=CopperSheetMaker.dayTimer+dt; if CopperSheetMaker.dayTimer>=30 then CopperSheetMaker.dayTimer=0; for i=#CopperSheetMaker.activeMaking,1,-1 do local m=CopperSheetMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CopperSheetMaker.completeMaking(m); table.remove(CopperSheetMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CopperSheetMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CopperSheetMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CopperSheetMaker.getStats() return {copperStock=CopperSheetMaker.copperStock,bronzeStock=CopperSheetMaker.bronzeStock,silverStock=CopperSheetMaker.silverStock,goldStock=CopperSheetMaker.goldStock,jewelStock=CopperSheetMaker.jewelStock,pearlStock=CopperSheetMaker.pearlStock,productStock=CopperSheetMaker.productStock,numBuildings=#CopperSheetMaker.buildings,hasMaker=CopperSheetMaker.maker~=nil,makerName=CopperSheetMaker.maker and CopperSheetMaker.maker.name or "—",makerSkill=CopperSheetMaker.maker and CopperSheetMaker.maker.skill or 0,activeMaking=#CopperSheetMaker.activeMaking,totalProducts=CopperSheetMaker.totalProducts} end
return CopperSheetMaker
